import {esc,money,date,readLocal,writeLocal,api,metric,link,privateLink,publicBuild,labels,specRows,differences,snapshot,modelName,captureThumb,compressImage,copy,saveFile} from './core.mjs';
import {FOSTINIS_VIDEOS} from './videos.mjs';
import {openReveal} from './reveal.mjs';
import {parseBuildBackup,serializeBuildBackup} from '../sharing/saved-builds.mjs';
const F=window.Fostinis,studio=window.FostinisStudio;
const TOKEN_KEY='fostinis-collection-access-v1',CACHE_KEY='fostinis-collection-cache-v1',JOURNAL_KEY='fostinis-journals-v1';
let root,collection,collectionToken,collectionLoading,activeDialog,materialsCleanup;
const view=new URLSearchParams(location.search).get('view')||'home';
const photo=name=>'/assets/heritage/'+name+'-1200.webp';
const btn=(text,action,extra='')=>`<button type="button" class="at-button" data-at="${action}" ${extra}>${text}</button>`;
const a=(text,url,primary=false)=>`<a class="at-button${primary?' at-primary':''}" href="${esc(url)}">${text}</a>`;
const intro=(eyebrow,title,text)=>`<div class="at-page-head"><span class="at-kicker">${eyebrow}</span><h1>${title}</h1><p>${text}</p></div>`;
function toast(message){let box=document.getElementById('atelier-toast');if(!box){box=document.createElement('div');box.id='atelier-toast';box.setAttribute('role','status');document.body.append(box);}box.textContent=message;box.hidden=false;clearTimeout(box.timer);box.timer=setTimeout(()=>box.hidden=true,6500);}
function dialog(html){activeDialog?.close();const d=document.createElement('dialog');d.className='at-dialog';d.setAttribute('aria-label','Fostinis atelier');d.innerHTML=html;document.body.append(d);d.addEventListener('click',e=>{if(e.target.closest('[data-close]'))d.close();});d.addEventListener('close',()=>{d.remove();if(activeDialog===d)activeDialog=null;},{once:true});activeDialog=d;return d;}
function modal(title,body,wide=false){const d=dialog(`<div class="at-dialog-head"><h2>${title}</h2><button data-close aria-label="Close dialog">×</button></div>${body}`);if(wide)d.classList.add('at-wide');d.showModal();return d;}
function videoCard(v,image){return `<article class="at-video-card"><button class="at-video-thumb" type="button" data-at="video" data-id="${v.id}" aria-label="Play ${esc(v.title)}"><img src="${image||'https://i.ytimg.com/vi/'+v.id+'/hqdefault.jpg'}" alt="${esc(v.title)}" loading="lazy"><span class="at-play" aria-hidden="true">▶</span><span class="at-duration">${v.duration}</span></button><div><span class="at-kicker">${v.category==='workshop'?'FROM THE WORKSHOP':'FOSTINIS ON FILM'}</span><h3>${esc(v.title)}</h3><p>${esc(v.note)}</p></div></article>`;}
function playVideo(id,title){if(!/^[\w-]{11}$/.test(id))return;const v=FOSTINIS_VIDEOS.find(v=>v.id===id);const d=modal(esc(title||v?.title||'Fostinis on film'),`<div class="at-video-player"><iframe src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0" title="${esc(title||v?.title||'Fostinis video')}" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p>${esc(v?.note||'Submitted to the Fostinis Circle.')}</p><a class="at-text-link" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">Watch on YouTube ↗</a>`,true);d.addEventListener('close',()=>d.querySelector('iframe')?.remove(),{once:true});}
function header(){return `<header class="at-header"><a href="/atelier.html" class="at-brand" aria-label="Fostinis atelier home"><img src="/assets/heritage/signature-240.webp" alt="" width="54" height="42"><span>FOSTINIS<small>G U I T A R S</small></span></a><nav aria-label="Atelier navigation">${[['home','Atelier'],['materials','Wood library'],['circle','The Circle'],['collection','My collection']].map(([id,label])=>`<a href="${link(id)}" ${view===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>${a('Design your guitar ↗','/showroom.html#builder',true)}</header>`;}
function footer(){return `<footer class="at-footer"><div><span class="at-wordmark">FOSTINIS</span><p>Three personalities. One personal instrument.</p></div><nav aria-label="Atelier footer"><a href="/showroom.html">Showroom</a><a href="${link('sound')}">Listen</a><a href="${link('craft')}">The craft</a><a href="${link('journal')}">My journal</a><a href="/contact.html#contact">Contact</a><a href="${link('workshop')}">Workshop desk</a></nav><small>Fostinis Guitars · Made personal.</small></footer>`;}
function home(){return `<section class="at-hero"><img class="at-hero-image" src="${photo('home-gallery-1-07')}" alt="Photographed amber Fostinis guitar, showing its carved top and wood figure" fetchpriority="high"><div class="at-hero-shade"></div><div class="at-hero-copy"><span class="at-kicker">THE FOSTINIS ATELIER</span><h1>A guitar only<br>you could imagine.</h1><p>Find your shape. Follow the grain.<br>Give your sound a signature.</p><div class="at-actions">${a('Begin your design','/showroom.html#builder',true)}${a('Hear a Fostinis ↗',link('sound'))}</div></div><div class="at-hero-foot"><span>DESIGNED AROUND YOU</span><a href="#at-discover">Explore the atelier ↓</a><span>SPHYX / ORYX / MATADAUR</span></div></section>
 <section class="at-section" id="at-discover"><div class="at-section-heading"><div><span class="at-kicker">THE MAKING OF YOURS</span><h2>It starts with a feeling.</h2></div><p>The shape that catches your eye. A color you keep returning to. The sound you hear before the first note.</p></div><div class="at-editorial-grid"><a class="at-editorial-card at-tall" href="${link('materials')}"><img src="/assets/wood-real19-flame.jpg" alt="Flame maple figure" loading="lazy"><div><span class="at-kicker">01 / THE MATERIAL</span><h3>Follow the grain.</h3><p>Explore figured woods under changing light.</p><span>Enter the wood library ↗</span></div></a><a class="at-editorial-card" href="${link('collection')}"><img src="${photo('home-gallery-2-06')}" alt="Photographed purple and green Fostinis guitar" loading="lazy"><div><span class="at-kicker">02 / YOUR COLLECTION</span><h3>Keep the possibilities.</h3><p>Name your designs. Compare your favorites. Return when inspiration calls.</p><span>Open my collection ↗</span></div></a><a class="at-editorial-card" href="${link('circle')}"><img src="${photo('mike-kyre')}" alt="Fostinis artist Mike Kyre" loading="lazy"><div><span class="at-kicker">03 / THE CIRCLE</span><h3>Share the obsession.</h3><p>Meet the music, the players, and the people behind it.</p><span>Discover the Circle ↗</span></div></a></div></section>
 <section class="at-split at-cream"><div class="at-split-media"><img src="${photo('home-gallery-1-03')}" alt="Fostinis signature headstock with gold hardware" loading="lazy"></div><div class="at-split-copy"><span class="at-kicker">THE DETAILS BECOME YOURS</span><h2>Put your name<br>to the moment.</h2><p>Once your design feels right, give it a name and reveal it in a cinematic portrait. Save your film, share the exact configuration, and invite a friend into the decision.</p><div class="at-actions">${btn('Reveal my current design','reveal')}${a('Explore the craft ↗',link('craft'))}</div></div></section>
 <section class="at-section"><div class="at-section-heading"><div><span class="at-kicker">REAL GUITARS. REAL PLAYERS.</span><h2>Hear what moves you.</h2></div>${a('All performances ↗',link('sound'))}</div><div class="at-grid at-two">${videoCard(FOSTINIS_VIDEOS[0],photo('peter-henningsson'))}${videoCard(FOSTINIS_VIDEOS[1],photo('mike-kyre'))}</div></section>
 <section class="at-invitation"><span class="at-kicker">A PERSONAL CONVERSATION</span><h2>Your vision.<br>Our next conversation.</h2><p>Send your exact design to Dimitris with the details that matter to you: your playing style, preferred setup, and what you want this instrument to become.</p>${a('Request a personal design review',link('commission'),true)}<span class="at-small">Your configuration travels with your request.</span></section>`;}
function sound(){return `${intro('THE LISTENING ROOM','Watch it. Hear it. Feel it.','Performances and reviews from the Fostinis Guitars channel, alongside the interactive playroom for your own design.')}<section class="at-section at-topless"><div class="at-callout"><div><h2>Put your design in your hands.</h2><p>Play notes and chords, explore pickup positions, and watch your configured guitar respond.</p></div>${btn('Open the playroom ↗','play')}</div><p class="at-small">Channel videos showcase real Fostinis instruments. They are not exact recordings of your selected pickups or wiring. The playroom labels its synthesized tone study and manufacturer references separately.</p><div class="at-filter" role="group" aria-label="Filter performances">${['all','sphyx','matadaur','workshop'].map((f,i)=>`<button data-at="filter-video" data-filter="${f}" aria-pressed="${i===0}">${f==='all'?'All films':f==='workshop'?'Workshop':modelName(f)}</button>`).join('')}</div><div class="at-grid at-two" id="at-videos">${FOSTINIS_VIDEOS.map(v=>`<div data-film-model="${v.model}" data-film-category="${v.category}">${videoCard(v)}</div>`).join('')}</div><p class="at-small">No Oryx sound demonstration has been identified in the channel catalog. New recordings can be submitted through the Circle.</p><a class="at-text-link" href="https://www.youtube.com/@fostinisguitars" target="_blank" rel="noopener noreferrer">Visit Fostinis Guitars on YouTube ↗</a></section>`;}
function craft(){return `${intro('THE FOSTINIS STANDARD','Look closer.','The instrument lives in the details. Explore photographs of actual Fostinis guitars and footage from the workshop archive.')}<section class="at-section at-topless"><div class="at-craft-grid">${[['home-gallery-1-07','The carved top','A closer look at the contour, binding, and transition into the wood figure.'],['home-gallery-1-13','The finish','Light moves across the figure and reveals a different part of the grain.'],['home-gallery-1-03','The signature','Headstock, hardware, and signature form one final detail.']].map(([im,h,p])=>`<article><button class="at-photo-zoom" data-at="photo" data-image="${im}" data-title="${h}"><img src="${photo(im)}" alt="${h}: actual Fostinis guitar photograph" loading="lazy"><span>Examine photograph ↗</span></button><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="at-section-heading"><div><span class="at-kicker">WORKSHOP ARCHIVE</span><h2>See the process.</h2></div><p>Real build footage, with the original workshop and music credits.</p></div><div class="at-grid at-two">${FOSTINIS_VIDEOS.filter(v=>v.category==='workshop').map(v=>videoCard(v)).join('')}</div><div class="at-callout"><div><h2>Make the setup personal.</h2><p>Tell us about your tuning, strings, playing style, and the neck feel you prefer. Confirm the details in your design review.</p></div>${a('Discuss my guitar',link('commission'),true)}</div></section>`;}
const WOODS=[['flame','Flame maple','Broad ribbons of figure catch the light across the grain.','wood-real19-flame.jpg'],['quilt','Quilted Bigleaf maple','Soft, irregular waves with a deep, cloudlike appearance.','wood-real19-quilt.jpg'],['burl','Burl','Tight eyes and swirling figure. Some blanks may require resin filling.','wood-real44-burl.jpg'],['ash','Ash','Open, flowing grain with a clear linear rhythm.','wood-real19-ash.jpg'],['walnut','Walnut','Warm brown tones and long, natural grain lines.','wood-real19-walnut.jpg'],['mahogany','Red mahogany','A warm red-brown example with fine, lengthwise grain.','wood-real19-mahogany.jpg']];
function materials(){return `${intro('THE WOOD LIBRARY','Nature, with a signature.','Explore representative wood blanks in three dimensions. Turn them, bring the grain closer, and see how the figure responds to light.')}<section class="at-section at-topless"><div class="at-material-layout"><div><div class="at-wood-viewer" id="at-wood-viewer" aria-label="Interactive representative wood blank"><img src="/assets/wood-real19-flame.jpg" alt="Representative flame maple grain"><p role="status">Preparing your wood sample…</p></div><p class="at-small">Drag to rotate · Pinch or scroll to zoom · Arrow keys to turn</p><div class="at-material-controls"><label>Surface <select id="at-wood-sheen"><option value="raw">Unfinished appearance</option><option value="satin">Clear satin</option><option value="gloss">Clear gloss</option></select></label><label>Move the light <input type="range" min="-90" max="90" value="-30" id="at-wood-light"></label><button id="at-wood-reset">Reset view</button></div></div><div class="at-material-info"><span class="at-kicker">REPRESENTATIVE MATERIAL / NOT INVENTORY</span><h2 id="at-wood-name">Flame maple</h2><p id="at-wood-copy">${WOODS[0][2]}</p><div class="at-wood-swatches">${WOODS.map(([id,name,,im],i)=>`<button data-at="wood" data-wood="${id}" aria-pressed="${i===0}"><img src="/assets/${im}" alt=""><span>${name}</span></button>`).join('')}</div><label>Add this wood to <select id="at-wood-region"><option value="wood">Guitar top</option><option value="backWood">Body back</option><option value="neckWood">Neck</option></select></label><button class="at-button at-primary" data-at="apply-wood">Use flame maple in my design ↗</button><p class="at-small">Illustrative material samples, including generated burl imagery. Grain, color, bookmatching, and finish vary from piece to piece and by screen. Final wood selection is confirmed with your build; these are not individual blanks offered for reservation.</p></div></div></section>`;}
async function loadCollection(){if(collectionLoading)return collectionLoading;collectionLoading=(async()=>{const access=new URLSearchParams(location.hash.slice(1)).get('access');collectionToken=(view==='collection'&&access)||readLocal(TOKEN_KEY,'');if(collectionToken){const result=await api('collection',{token:collectionToken});collection=result;writeLocal(TOKEN_KEY,collectionToken);writeLocal(CACHE_KEY,result);}else collection={name:'My Fostinis Collection',revision:0,builds:readLocal('fostinis-saved-builds-v1',[]).slice(0,20)};return collection;})();try{return await collectionLoading;}finally{collectionLoading=null;}}
async function storeCollection(builds){const result=await api('collection',{token:collectionToken||undefined,data:{builds,name:collection?.name||'My Fostinis Collection',revision:collection?.revision||0}});collectionToken=result.token||collectionToken;collection=result;writeLocal(TOKEN_KEY,collectionToken);writeLocal(CACHE_KEY,result);return result;}
function buildCard(b,{select=false,vote=false,count=0}={}){const l=labels(b);return `<article class="at-build-card">${b.image?`<img class="at-build-preview" src="${esc(b.image)}" alt="Saved configured ${esc(modelName(b.model))}">`:`<div class="at-build-placeholder"><span>${esc(modelName(b.model))}</span><small>Open the design to see its configured preview.</small></div>`}<div class="at-build-card-copy"><span class="at-kicker">${esc(modelName(b.model))} / ${b.selections.handedness==='left'?'LEFT':'RIGHT'} HANDED</span><h3>${esc(b.name||b.nickname||'My '+modelName(b.model))}</h3><p>${esc(l.wood)} · ${esc(l.finish)}<br>${esc(l.pickupLayout)} · ${esc(l.bridgeModel)}</p>${vote?`<button class="at-button at-primary" data-at="vote" data-id="${esc(b.id)}">Choose this guitar · ${count} vote${count===1?'':'s'}</button>`:`<div class="at-actions">${a('Open design ↗',publicBuild(b))}${btn('Resume','resume',`data-id="${esc(b.id)}"`)}</div>${select?`<label class="at-check"><input type="checkbox" name="compare" value="${esc(b.id)}"> Compare this design</label><div class="at-card-minor"><button data-at="rename" data-id="${esc(b.id)}">Rename</button><button data-at="remove" data-id="${esc(b.id)}">Remove</button></div>`:''}`}</div></article>`;}
async function collectionPage(){root.innerHTML=header()+intro('YOUR PERSONAL DESIGN COLLECTION','Keep what moves you.','Save a named version, explore another direction, and compare the guitars you keep coming back to.')+`<section class="at-section at-topless"><div class="at-collection-toolbar"><div class="at-actions">${btn('Save current design +','save')}${btn('Compare two designs','compare')}${btn('My private access link','collection-link')}</div><div class="at-actions">${btn('Export backup','backup')}<label class="at-upload">Import backup<input type="file" accept=".json,application/json" id="at-import"></label></div></div><p class="at-status" id="at-collection-status" role="status">Opening your collection…</p><div class="at-grid at-two" id="at-builds"></div><div class="at-callout"><div><h3>A collection that comes with you.</h3><p>Save your private access link to open these designs on another device. Anyone with that link can edit the collection. Share individual design links or a comparison when inviting friends.</p></div>${a('Explore another design ↗','/showroom.html#builder')}</div></section>`+footer();try{await loadCollection();refreshCollection();}catch(e){document.getElementById('at-collection-status').textContent=e.message+' Your current working guitar is still in the builder.';}}
function refreshCollection(){document.getElementById('at-builds').innerHTML=collection.builds.length?collection.builds.map(b=>buildCard(b,{select:true})).join(''):`<div class="at-empty"><span class="at-kicker">YOUR FIRST CHAPTER</span><h2>One idea can become a collection.</h2><p>Save your current design, then try another finish or model. Your favorites will appear here.</p>${btn('Save my current design','save')}</div>`;document.getElementById('at-collection-status').textContent=collectionToken?`${collection.builds.length} of 20 designs · Saved online. Keep your private link for another device.`:'Your saved browser builds are ready to move into a private online collection when you save.';}
async function saveCurrent(){const build=snapshot();const d=modal('Keep this possibility.',`<form id="at-save-form"><label>Name your design<input name="name" maxlength="40" value="${esc(build.nickname||'My '+modelName(build.model))}" required></label><p>${esc(modelName(build.model))} · ${esc(labels(build).finish)} · ${esc(labels(build).wood)}</p><button class="at-button at-primary">Save to my collection</button><p class="at-status" role="status"></p></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('button'),s=form.querySelector('.at-status');b.disabled=true;s.textContent='Capturing your configured guitar…';try{await loadCollection();if(collection.builds.length>=20)throw Error('Your collection has 20 designs. Export or remove one to make room.');let image='';try{image=await captureThumb();}catch{}const time=new Date().toISOString(),record={...build,name:form.elements.name.value.trim(),nickname:form.elements.name.value.trim(),id:crypto.randomUUID(),createdAt:time,updatedAt:time,image};await storeCollection([record,...collection.builds]);metric('build_saved');s.innerHTML=`Saved.${image?'':' The preview could not be captured on this device; your specifications are saved.'} <a href="${link('collection')}">Open my collection ↗</a>`;b.textContent='Saved to collection';if(view==='collection'&&root)refreshCollection();}catch(error){s.textContent=error.message;b.disabled=false;}};}
async function collectionLink(){if(!collection)await loadCollection();if(!collectionToken)await storeCollection(collection.builds);showLink('Your private collection link',privateLink('collection',collectionToken),'Keep this link private. Anyone who has it can view and edit this collection. Save it before clearing your browser data.');}
function showLink(title,url,caption){const d=modal(title,`<p>${caption}</p><label>Access link<input readonly value="${esc(url)}"></label><div class="at-actions"><button class="at-button at-primary" data-copy-link>Copy link</button><a class="at-button" href="mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(url)}">Open email draft ↗</a></div><p role="status" class="at-status"></p>`);d.querySelector('input').onclick=e=>e.target.select();d.querySelector('[data-copy-link]').onclick=async()=>{try{await copy(url);d.querySelector('.at-status').textContent='Link copied.';}catch(e){d.querySelector('.at-status').textContent=e.message;}};}
async function compare(){if(!collection)await loadCollection();const ids=[...document.querySelectorAll('[name=compare]:checked')].map(x=>x.value);if(ids.length!==2)throw Error('Select exactly two saved designs to compare.');const builds=ids.map(id=>collection.builds.find(b=>b.id===id)),diff=differences(...builds);const d=modal('Which one feels like you?',`<div class="at-grid at-two">${builds.map(b=>buildCard(b)).join('')}</div><div class="at-table-scroll"><table><caption>What changes between your designs</caption><thead><tr><th>Appointment</th>${builds.map(b=>`<th>${esc(b.name)}</th>`).join('')}</tr></thead><tbody><tr><th>Model</th>${builds.map(b=>`<td>${esc(modelName(b.model))}</td>`).join('')}</tr>${diff.map(r=>`<tr><th>${r.label}</th><td>${esc(r.a)}</td><td>${esc(r.b)}</td></tr>`).join('')}</tbody></table></div>${!diff.length?'<p>These designs use the same appointments.</p>':''}<button class="at-button at-primary" data-poll>Create a friend comparison</button><p class="at-small">Creates a link anyone with it can open and vote on. Your build notes and private collection link stay out of it.</p><p class="at-status" role="status"></p>`,true);d.querySelector('[data-poll]').onclick=async e=>{e.target.disabled=true;try{const result=await api('poll',{data:{options:builds}});showLink('Help me choose my Fostinis',location.origin+link('compare',{id:result.id}),'Send this comparison to your friends. They can vote without changing your saved guitars.');}catch(error){d.querySelector('.at-status').textContent=error.message;e.target.disabled=false;}};}
async function pollPage(){root.innerHTML=header()+intro('A LITTLE HELP FROM YOUR FRIENDS','Which guitar would you choose?','Two personal designs. Pick your favorite and help shape the decision.')+`<section class="at-section at-topless"><p class="at-status" role="status">Loading the comparison…</p><div class="at-grid at-two" id="at-poll"></div></section>`+footer();const id=new URLSearchParams(location.search).get('id');try{const result=await api('poll',{query:'?id='+encodeURIComponent(id||'')});root.querySelector('#at-poll').innerHTML=result.options.map(b=>buildCard(b,{vote:true,count:result.votes.find(v=>v.option_id===b.id)?.count||0})).join('');root.querySelector('.at-status').textContent='One vote per browser; choosing again changes your vote. Design links open an independent copy.';}catch(e){root.querySelector('.at-status').textContent=e.message;}}
function contactFields(){return `<div class="at-form-grid"><label>Your name<input name="name" required maxlength="100" autocomplete="name"></label><label>Email address<input name="email" type="email" required maxlength="240" autocomplete="email"></label></div><label class="at-honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label>`;}
async function commissionPage(){const build=snapshot(),name=build.nickname||'Your '+modelName(build.model);metric('commission_opened');root.innerHTML=header()+intro('YOUR PERSONAL COMMISSION','Let’s make it yours.','Your choices are a starting point for a personal conversation. Review the specification, tell us how you play, and decide your next step.')+`<section class="at-section at-topless"><div class="at-commission-grid"><aside class="at-commission-summary"><span class="at-kicker">YOUR CURRENT DESIGN</span><h2>${esc(name)}</h2><div id="at-commission-preview" class="at-commission-preview"><p>Preparing your configured guitar…</p></div><div id="at-quote"><p>Confirming the current build price…</p></div><details><summary>All appointments</summary><dl class="at-specs">${specRows(build)}</dl></details><div class="at-actions">${a('Edit this design','/showroom.html#builder')}${btn('Reveal','reveal')}</div></aside><div><ol class="at-steps"><li><span>01</span><div><h3>Make it personal</h3><p>Your exact configuration accompanies the design-review request.</p></div></li><li><span>02</span><div><h3>Confirm the details</h3><p>Discuss setup, final material selection, build timing, and delivery before committing.</p></div></li><li><span>03</span><div><h3>Follow its story</h3><p>Your private journal holds the review and the workshop updates added for your guitar.</p></div></li></ol><form class="at-form" id="at-review-form"><h2>A conversation with Dimitris.</h2>${contactFields()}<label>Your playing style and setup<textarea name="message" required rows="5" maxlength="3000" placeholder="What do you play? Tell us about your tuning, preferred strings, neck feel, and anything you would like to discuss."></textarea></label><p class="at-small">Your name, email, design, and message are shared privately with the Fostinis workshop for this request. Save the private journal link shown after submission.</p><button class="at-button at-primary">Request my personal design review</button><p class="at-status" role="status"></p></form><div class="at-purchase"><h3>Ready to commission your guitar?</h3><p>Review the complete price, payment options, and order terms in your build. Checkout currently takes the full order payment. Final tax and any applicable delivery details appear before payment.</p>${a('Review price & order terms ↗','/review.html#build-checkout')}<p class="at-small" id="at-lead-time">Build timing is confirmed during your design review.</p></div></div></div></section>`+footer();bindRequest(root.querySelector('form'),'review',build);captureThumb().then(image=>{const box=document.getElementById('at-commission-preview');if(box)box.innerHTML=`<img src="${image}" alt="Your configured ${esc(modelName(build.model))}">`;}).catch(()=>{const box=document.getElementById('at-commission-preview');if(box)box.textContent='Your full configuration is included below. Open the showroom for its preview.';});try{const response=await fetch('/api/commerce/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(build)});const q=await response.json();if(!response.ok)throw Error(q.message);document.getElementById('at-quote').innerHTML=`<span class="at-kicker">CONFIGURED GUITAR / USD</span><strong class="at-price">${money(q.confirmedSubtotalCents)}</strong><p class="at-small">${q.unresolved.length?'Some choices require confirmation.':'Selected appointments included.'} ${q.shippingCents===0?'US shipping included.':''} Final tax confirmed at checkout.</p>`;}catch{document.getElementById('at-quote').textContent='The price could not be loaded. Open your build to review it.';}api('circle').then(data=>{const value=data.settings.find(s=>s.key==='leadTime')?.value;if(value&&document.getElementById('at-lead-time'))document.getElementById('at-lead-time').textContent=value;}).catch(()=>{});}
function bindRequest(form,kind,build){form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])'),status=form.querySelector('.at-status');button.disabled=true;status.textContent='Saving your request…';try{const values=Object.fromEntries(new FormData(form));let image='';const file=form.querySelector('[name=photo]')?.files?.[0];if(file){if(file.size>12*1024*1024)throw Error('Choose a photo smaller than 12 MB.');image=await compressImage(file);}const response=await api('request',{data:{...values,kind,build,image,consent:!!form.querySelector('[name=consent]:checked')}});const url=privateLink('journal',response.token),saved=readLocal(JOURNAL_KEY,[]);writeLocal(JOURNAL_KEY,[{id:response.id,name:build?.nickname||values.title||'My '+(kind==='review'?'design review':'Circle request'),token:response.token,createdAt:new Date().toISOString()},...saved].slice(0,20));form.innerHTML=`<div class="at-success"><span class="at-kicker">REQUEST RECEIVED</span><h2>${kind==='review'?'Your next chapter begins here.':'You’re part of the conversation.'}</h2><p>${kind==='review'?'Your design and message are saved for the workshop. This is a review request; it does not place an order or reserve a production slot.':kind==='story'?'Your submission is saved for review. It will appear publicly only after approval.':'Your interest is saved for the workshop. Scheduled gatherings will appear on the Circle page.'}</p><a class="at-button at-primary" href="${url}">Open my private journal ↗</a><p class="at-small">Save this private link for another device. No automatic email has been sent.</p><label>Your access link<input readonly value="${url}"></label><button type="button" class="at-button" data-copy-receipt>Copy private link</button><p class="at-status" role="status"></p></div>`;form.querySelector('[data-copy-receipt]').onclick=async()=>{try{await copy(url);form.querySelector('.at-status').textContent='Private link copied.';}catch(e){form.querySelector('.at-status').textContent=e.message;}};}catch(e){status.textContent=e.message;button.disabled=false;}};}
async function circlePage(){root.innerHTML=header()+`<section class="at-circle-hero"><img src="${photo('mark-slaughter')}" alt="Mark Slaughter performing with Fostinis" fetchpriority="high"><div><span class="at-kicker">THE FOSTINIS CIRCLE</span><h1>Different players.<br>The same obsession.</h1><p>A place for the music, the ideas, and the instruments that bring us together.</p><div class="at-actions">${btn('Join the Circle','join-circle')}${btn('Share my story','submit-story')}</div></div></section><section class="at-section"><div class="at-section-heading"><div><span class="at-kicker">IN GOOD COMPANY</span><h2>Let the players speak.</h2></div><p>Performances from the Fostinis archive, in each artist’s own musical voice.</p></div><div class="at-grid at-three">${videoCard(FOSTINIS_VIDEOS[0],photo('peter-henningsson'))}${videoCard(FOSTINIS_VIDEOS[1],photo('mike-kyre'))}${videoCard(FOSTINIS_VIDEOS.find(v=>v.id==='cfnnlJms8UA'),photo('mark-slaughter'))}</div><div class="at-section-heading"><div><span class="at-kicker">FROM THE CIRCLE</span><h2>Every guitar has a story.</h2></div>${btn('Submit yours ↗','submit-story')}</div><div id="at-stories" class="at-grid at-three"><p class="at-status">Opening the Circle…</p></div><div class="at-section-heading"><div><span class="at-kicker">COME CLOSER</span><h2>The next gathering.</h2></div><p>Workshop conversations, listening sessions, and chances to share what you are making.</p></div><div id="at-events"></div><div class="at-callout"><div><h3>Belong before the first note.</h3><p>You can join the conversation while designing your first Fostinis. Share a concept, send a performance, or register your interest in future sessions.</p></div>${btn('Join the Circle','join-circle')}</div></section>`+footer();try{const data=await api('circle');root.querySelector('#at-stories').innerHTML=data.stories.length?data.stories.map(s=>`<article class="at-story">${s.image?`<img src="${esc(s.image)}" alt="${esc(s.title)}" loading="lazy">`:''}<span class="at-kicker">${s.kind==='owner'?'OWNER STORY':'COMMUNITY SUBMISSION'}</span><h3>${esc(s.title)}</h3><p>${esc(s.story)}</p><span>Shared by ${esc(s.author)}</span><div class="at-actions">${s.video_id?btn('Watch the story','video',`data-id="${s.video_id}"`):''}${s.build?a('Explore this design ↗',publicBuild(s.build)):''}</div></article>`).join(''):`<div class="at-empty"><h3>Your story could be the first.</h3><p>Share a design, a performance, or the story behind your guitar. Submissions are reviewed before appearing here.</p>${btn('Share my story','submit-story')}</div>`;root.querySelector('#at-events').innerHTML=data.events.length?data.events.map(e=>`<article class="at-event"><time datetime="${e.starts_at}">${date(e.starts_at)}<small>${new Date(e.starts_at).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',timeZoneName:'short'})}</small></time><div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p></div>${e.url?a('Event details ↗',e.url):''}</article>`).join(''):'<div class="at-empty at-small-empty"><h3>The next date is still being planned.</h3><p>Register your interest to let the workshop know what you would like to see.</p></div>';}catch{root.querySelector('#at-stories').textContent='The Circle could not be loaded. Please try again shortly.';root.querySelector('#at-events').textContent='Event information is temporarily unavailable.';}}
function circleForm(story=false){const d=modal(story?'What’s your Fostinis story?':'Welcome to the Circle.',`<form class="at-form">${contactFields()}${story?`<label>Story title<input name="title" maxlength="100" required></label><label>Your story<textarea name="message" rows="4" maxlength="3000" required></textarea></label><label>YouTube video link <small>(optional)</small><input name="videoUrl" type="url" placeholder="https://www.youtube.com/watch?v=…"></label><label>Your photograph <small>(optional, up to 12 MB)</small><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="at-check"><input type="checkbox" name="attach" checked> Include my current guitar design</label><label class="at-check"><input type="checkbox" name="consent" required> I have permission to share this content and agree that Fostinis may publish my name, story, attached design, photo, and video after review.</label>`:`<label>What would you like to be part of?<select name="interest"><option>Workshop conversations</option><option>Artist listening sessions</option><option>Design and finish previews</option><option>Owner gatherings</option></select></label><label>A note for the workshop <small>(optional)</small><textarea name="message" rows="3" maxlength="3000"></textarea></label><p class="at-small">Your contact details stay with the workshop. Registering interest does not book an event or purchase a membership.</p>`}<button class="at-button at-primary">${story?'Submit for review':'Register my interest'}</button><p class="at-status" role="status"></p></form>`);const form=d.querySelector('form');const attach=form.querySelector('[name=attach]');bindRequest(form,story?'story':'circle',story?snapshot():null);if(attach)attach.onchange=()=>bindRequest(form,'story',attach.checked?snapshot():null);}
async function journalPage(){const token=new URLSearchParams(location.hash.slice(1)).get('access');root.innerHTML=header()+intro('YOUR PRIVATE JOURNAL','The story of your instrument.','Your design review, workshop updates, and final instrument details, together in one place.')+`<section class="at-section at-topless" id="at-journal"><p role="status">Opening your journal…</p></section>`+footer();const box=document.getElementById('at-journal');if(!token){const journals=readLocal(JOURNAL_KEY,[]);box.innerHTML=journals.length?`<div class="at-grid at-two">${journals.map(j=>`<article class="at-journal-link"><span class="at-kicker">${date(j.createdAt)}</span><h3>${esc(j.name)}</h3>${a('Open private journal ↗',privateLink('journal',j.token))}</article>`).join('')}</div><p class="at-small">These links are remembered on this browser. Use the private link you saved to open a journal from another device.</p>`:`<div class="at-empty"><h2>Your story starts with a design.</h2><p>Request a personal design review to create a private journal, or open the private link you saved earlier.</p>${a('Request my design review',link('commission'),true)}</div>`;return;}try{const data=await api('journal',{token}),r=data.request,complete=['complete','delivered'].includes(r.status),stages=['design','confirmed','materials','construction','finishing','electronics','setup','complete','delivered'];box.innerHTML=`<div class="at-journal-heading"><div><span class="at-kicker">PRIVATE / ${esc(r.id)}</span><h2>${esc(r.build?.nickname||r.details?.title||r.name+'’s '+(r.kind==='review'?'guitar':'Circle request'))}</h2><p>Received ${date(r.createdAt)} · Current status: ${esc(r.status)}</p></div>${btn('Keep my access link','journal-link')}</div>${r.kind==='review'?`<ol class="at-progress" aria-label="Build stages">${stages.map((s,i)=>`<li ${r.status===s?'aria-current="step"':''} class="${i<=stages.indexOf(r.status)?'is-reached':''}"><span>${String(i+1).padStart(2,'0')}</span>${s}</li>`).join('')}</ol><p class="at-small">Stages change when the workshop posts an update. A design review is not a paid order or a reserved build slot.</p>`:''}<div class="at-journal-grid"><div class="at-timeline">${data.entries.length?data.entries.map(e=>`<article><time datetime="${e.created_at}">${date(e.created_at)}</time><span class="at-kicker">${esc(e.stage)}</span><h3>${esc(e.title)}</h3><p>${esc(e.note)}</p>${e.image?`<img src="${esc(e.image)}" alt="Workshop update: ${esc(e.title)}" loading="lazy">`:''}${e.video_id?btn('Watch workshop update','video',`data-id="${e.video_id}"`):''}</article>`).join(''):`<article><h3>Your request is with the workshop.</h3><p>${r.kind==='story'?'Your story is awaiting review. Approved stories appear on the Circle page.':'Your interest is saved. Visit the Circle for scheduled gatherings.'}</p></article>`}</div><aside class="at-passport"><span class="at-kicker">${complete?'INSTRUMENT PASSPORT':'DESIGN RECORD'}</span><h3>${esc(r.build?modelName(r.build.model):'Fostinis Circle')}</h3>${r.serial?`<p>Instrument serial: <strong>${esc(r.serial)}</strong></p>`:''}${r.orderId?'<p class="at-small">A paid website order is linked to this journal.</p>':''}${r.build?`<dl class="at-specs">${specRows(r.build)}</dl>${a('View the design ↗',publicBuild(r.build))}`:''}<details><summary>Your original message</summary><p>${esc(r.message)}</p></details>${btn('Download my record','passport')}<p class="at-small">Your journal link is private. Anyone with it can read these details.</p></aside></div>`;box.querySelector('[data-at=journal-link]').onclick=()=>showLink('Your private guitar journal',privateLink('journal',token),'Save this link to return on any device. Anyone with it can read your journal.');box.querySelector('[data-at=passport]').onclick=()=>saveFile(new Blob([JSON.stringify({format:'fostinis-instrument-record',version:1,exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'}),'Fostinis_'+r.id+'_Record.json');}catch(e){box.innerHTML=`<div class="at-empty"><h2>We could not open this journal.</h2><p>${esc(e.message)}</p>${a('My saved journal links',link('journal'))}</div>`;}}
let adminData;
async function workshopPage(){root.innerHTML=header()+intro('FOSTINIS / PRIVATE WORKSHOP DESK','The people behind the guitars.','Manage personal design reviews, publish approved community stories, and keep each customer’s instrument journal up to date.')+`<section class="at-section at-topless" id="at-admin"><p role="status">Checking workshop access…</p></section>`+footer();const box=document.getElementById('at-admin');try{const session=await api('session');if(!session.owner){box.innerHTML=`<div class="at-empty"><h2>Workshop owner access</h2><p>${session.signedIn?'This account is not authorized to open the Fostinis workshop desk. Sign in with the account that owns the site.':'Sign in with the ChatGPT account that owns the Fostinis website to manage requests and journals.'}</p>${a('Sign in with ChatGPT ↗',session.signIn,true)}</div>`;return;}const [data,circle]=await Promise.all([api('admin'),api('circle')]);adminData=data;box.innerHTML=`<div class="at-admin-metrics"><div><span class="at-kicker">LAST 30 DAYS</span><h3>Customer activity</h3><p>Aggregated interactions, not unique visitors.</p></div>${[['atelier_visit','Atelier visits'],['build_saved','Designs saved'],['review_requested','Review requests'],['story_requested','Stories received']].map(([key,label])=>`<div><strong>${data.metrics.find(m=>m.event===key)?.count||0}</strong><span>${label}</span></div>`).join('')}</div><div class="at-admin-layout"><section><h2>Requests & conversations</h2><label>Show <select id="at-request-filter"><option value="all">All requests</option><option value="review">Design reviews</option><option value="story">Community submissions</option><option value="circle">Circle interest</option></select></label><div id="at-admin-requests">${data.requests.length?data.requests.map(r=>`<article class="at-admin-request" data-kind="${r.kind}"><div><span class="at-kicker">${r.kind} / ${date(r.createdAt)}</span><h3>${esc(r.name)}</h3><p>${esc(r.build?.nickname||r.details?.title||r.details?.interest||r.email)}</p><span class="at-tag">${esc(r.status)}</span></div>${btn('Open request ↗','admin-request',`data-id="${esc(r.id)}"`)}</article>`).join(''):'<p class="at-empty">New requests will appear here.</p>'}</div></section><aside><form id="at-settings" class="at-form"><h3>Customer guidance</h3><label>Current build timing<textarea name="leadTime" rows="3" maxlength="600" placeholder="Add the current, confirmed lead-time guidance.">${esc(data.settings.find(s=>s.key==='leadTime')?.value||'')}</textarea></label><button class="at-button">Save timing guidance</button><p class="at-status" role="status"></p></form><form id="at-event-form" class="at-form"><h3>Schedule a Circle gathering</h3><label>Event title<input name="title" required maxlength="120"></label><label>Date and time <small>(your local time)</small><input name="startsAt" type="datetime-local" required></label><label>Description<textarea name="description" maxlength="1000" rows="3"></textarea></label><label>Event or booking link<input name="url" type="url" placeholder="https://…"></label><button class="at-button">Publish event</button><p class="at-status" role="status"></p></form><div class="at-admin-events">${circle.events.map(e=>`<article><h4>${esc(e.title)}</h4><p>${date(e.starts_at)}</p>${btn('Remove event','delete-event',`data-id="${esc(e.id)}"`)}</article>`).join('')}</div></aside></div>`;box.querySelector('#at-request-filter').onchange=e=>box.querySelectorAll('[data-kind]').forEach(x=>x.hidden=e.target.value!=='all'&&x.dataset.kind!==e.target.value);for(const [id,operation] of [['at-settings','settings'],['at-event-form','event']])box.querySelector('#'+id).onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,status=form.querySelector('.at-status'),button=form.querySelector('button');button.disabled=true;try{const values=Object.fromEntries(new FormData(form));if(values.startsAt)values.startsAt=new Date(values.startsAt).toISOString();await api('admin',{data:{operation,...values}});status.textContent='Saved.';if(operation==='event')await workshopPage();}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};}catch(e){box.textContent=e.message;}}
async function adminRequest(id){const r=adminData.requests.find(r=>r.id===id);if(!r)return;const details=r.details||{};const d=modal(esc(r.name)+' · '+esc(r.kind),`<div class="at-admin-request-detail"><a href="mailto:${encodeURIComponent(r.email)}?subject=${encodeURIComponent('Your Fostinis '+(r.kind==='review'?'design review':'Circle submission'))}">${esc(r.email)} ↗</a><p>${esc(r.message||'No additional message.')}</p>${details.interest?`<p>Interest: ${esc(details.interest)}</p>`:''}${details.image?`<img class="at-submission-photo" src="${esc(details.image)}" alt="Submitted photograph">`:''}${details.videoId?btn('Watch submitted video','video',`data-id="${details.videoId}"`):''}${r.build?`<details><summary>Submitted guitar configuration</summary><dl class="at-specs">${specRows(r.build)}</dl>${a('Open design ↗',publicBuild(r.build))}</details>`:''}<div class="at-actions">${['contacted','closed'].map(s=>`<button class="at-button" data-request-status="${s}">Mark ${s}</button>`).join('')}</div><p class="at-small">Email links open a draft in your mail app. This dashboard does not send email automatically.</p></div>${r.kind==='review'?`<div id="at-admin-history"><p>Loading journal history…</p></div><form class="at-form" id="at-journal-update"><h3>Add a private workshop update</h3><label>Stage<select name="stage">${['design','confirmed','materials','construction','finishing','electronics','setup','complete','delivered'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Update title<input name="title" required maxlength="120"></label><label>Note to your customer<textarea name="note" rows="4" maxlength="3000" required></textarea></label><div class="at-form-grid"><label>Workshop photo<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label>YouTube video URL<input name="videoUrl" type="url"></label></div><label>Instrument serial <small>(when assigned)</small><input name="serial" maxlength="80" value="${esc(r.serial)}"></label><label>Link a verified paid website order <small>(optional)</small><select name="orderId"><option value="">${r.orderId?'Keep linked order '+esc(r.orderId):'No order association'}</option>${adminData.orders.map(o=>`<option value="${esc(o.id)}">${esc(o.id)} · ${date(o.created_at)}</option>`).join('')}</select></label><p class="at-small">Verify the customer and configuration before linking an order. Completion and delivery stages should reflect actual workshop progress.</p><button class="at-button at-primary">Publish private update</button><p class="at-status" role="status"></p></form>`:r.kind==='story'?`<form class="at-form" id="at-story-publish"><h3>Review for the public Circle</h3><p>${details.consent?'Publication permission was included with this submission.':'No publication permission recorded.'}</p><label>Published title<input name="title" maxlength="120" required value="${esc(details.title)}"></label><label>Published story<textarea name="story" rows="5" maxlength="3000" required>${esc(r.message)}</textarea></label><label>Verified owner order <small>(optional)</small><select name="orderId"><option value="">Community submission</option>${adminData.orders.map(o=>`<option value="${esc(o.id)}">${esc(o.id)} · ${date(o.created_at)}</option>`).join('')}</select></label><p class="at-small">Verify this customer owns the order before linking it. The submitter’s name, approved text, attached design, photo, and video will be public.</p><button class="at-button at-primary" ${details.consent?'':'disabled'}>Publish approved story</button><button type="button" class="at-button" data-unpublish>Remove from Circle</button><p class="at-status" role="status"></p></form>`:''}<p class="at-status" id="at-admin-message" role="status"></p>`,true);const message=d.querySelector('#at-admin-message');for(const b of d.querySelectorAll('[data-request-status]'))b.onclick=async()=>{b.disabled=true;try{await api('admin',{data:{operation:'status',id,status:b.dataset.requestStatus}});r.status=b.dataset.requestStatus;message.textContent='Status saved.';}catch(e){message.textContent=e.message;}finally{b.disabled=false;}};if(r.kind==='review'){api('admin-journal',{query:'?id='+encodeURIComponent(id)}).then(data=>{const target=d.querySelector('#at-admin-history');if(target)target.innerHTML=`<h3>Journal history</h3>${data.entries.map(e=>`<details><summary>${date(e.created_at)} · ${esc(e.title)} · ${esc(e.stage)}</summary><p>${esc(e.note)}</p></details>`).join('')}`;}).catch(e=>d.querySelector('#at-admin-history').textContent=e.message);}for(const [selector,operation] of [['#at-journal-update','journal'],['#at-story-publish','publish-story']]){const form=d.querySelector(selector);if(!form)continue;form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button'),status=form.querySelector('.at-status');button.disabled=true;try{const values=Object.fromEntries(new FormData(form)),file=form.querySelector('[name=photo]')?.files?.[0];if(file&&file.size>12*1024*1024)throw Error('Choose a photo smaller than 12 MB.');const image=file?await compressImage(file):'';await api('admin',{data:{operation,id,...values,image}});status.textContent=operation==='journal'?'The customer’s private journal is updated.':'The approved story is now public in the Circle.';r.status=values.stage||'published';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};}d.querySelector('[data-unpublish]')?.addEventListener('click',async()=>{try{await api('admin',{data:{operation:'unpublish-story',id}});message.textContent='Story removed from the public Circle.';}catch(e){message.textContent=e.message;}});}
function addBuilderEntries(){const nav=document.querySelector('.topbar nav');if(nav){const entry=document.createElement('a');entry.href='/atelier.html';entry.textContent='Atelier & Circle';nav.append(entry);}const review=document.getElementById('build-checkout');if(review){const entry=document.createElement('div');entry.className='at-builder-entry';entry.innerHTML=`<span class="at-kicker">YOUR GUITAR, BEFORE THE FIRST NOTE</span><h3>Make it feel like yours.</h3><div class="at-actions">${btn('Save to my collection','save')}${btn('Cinematic reveal','reveal')}${a('Personal design review ↗',link('commission'))}</div><a href="${link('collection')}">Open my collection →</a>`;review.before(entry);}const dock=document.querySelector('.build-dock');if(dock){const entry=document.createElement('a');entry.href=link('collection');entry.textContent='My collection';entry.className='at-dock-link';dock.append(entry);}}
let woodId='flame';
async function handle(event){const b=event.target.closest('[data-at]');if(!b)return;const action=b.dataset.at;try{
 if(action==='video')playVideo(b.dataset.id);
 else if(action==='photo')modal(esc(b.dataset.title),`<img class="at-full-photo" src="${photo(b.dataset.image)}" alt="${esc(b.dataset.title)}">`,true);
 else if(action==='play'){if(window.FostinisPlayroom?.open)window.FostinisPlayroom.open();else document.querySelector('[data-open-playroom]')?.click();}
 else if(action==='reveal'){const d=dialog('');await openReveal(d);}
 else if(action==='save')await saveCurrent();
 else if(action==='collection-link')await collectionLink();
 else if(action==='compare')await compare();
 else if(action==='resume'){const record=collection?.builds.find(x=>x.id===b.dataset.id);if(record){studio.restoreBuild(record);location.href='/showroom.html#builder';}}
 else if(action==='backup'){if(!collection)await loadCollection();saveFile(new Blob([serializeBuildBackup(collection.builds)],{type:'application/json'}),'Fostinis_My_Collection.json');}
 else if(action==='remove'){const record=collection?.builds.find(x=>x.id===b.dataset.id);if(!record)return;const d=modal('Remove this saved design?',`<p>Remove “${esc(record.name)}” from this collection? Your current working design stays in the builder.</p><button class="at-button" data-remove-confirm>Remove saved design</button><p class="at-status" role="status"></p>`);d.querySelector('[data-remove-confirm]').onclick=async e=>{e.target.disabled=true;try{await storeCollection(collection.builds.filter(x=>x.id!==record.id));d.close();refreshCollection();}catch(error){d.querySelector('.at-status').textContent=error.message;e.target.disabled=false;}};}
 else if(action==='rename'){const record=collection?.builds.find(x=>x.id===b.dataset.id);if(!record)return;const d=modal('Name this possibility.',`<form><label>Design name<input name="name" required maxlength="40" value="${esc(record.name)}"></label><button class="at-button at-primary">Save name</button><p class="at-status" role="status"></p></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{const name=form.elements.name.value.trim();await storeCollection(collection.builds.map(x=>x.id===record.id?{...x,name,nickname:name}:x));d.close();refreshCollection();}catch(error){form.querySelector('.at-status').textContent=error.message;}};}
 else if(action==='vote'){b.disabled=true;let voter=readLocal('fostinis-comparison-voter','');if(!voter){voter=crypto.randomUUID();writeLocal('fostinis-comparison-voter',voter);}await api('vote',{data:{id:new URLSearchParams(location.search).get('id'),optionId:b.dataset.id,voter}});await pollPage();toast('Your vote is saved.');}
 else if(action==='filter-video'){root.querySelectorAll('[data-film-model]').forEach(card=>card.hidden=b.dataset.filter!=='all'&&(b.dataset.filter==='workshop'?card.dataset.filmCategory!=='workshop':card.dataset.filmModel!==b.dataset.filter||card.dataset.filmCategory==='workshop'));root.querySelectorAll('[data-at=filter-video]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}
 else if(action==='join-circle')circleForm();
 else if(action==='submit-story')circleForm(true);
 else if(action==='admin-request')await adminRequest(b.dataset.id);
 else if(action==='delete-event'){await api('admin',{data:{operation:'delete-event',id:b.dataset.id}});await workshopPage();}
 else if(action==='wood'){woodId=b.dataset.wood;const wood=WOODS.find(x=>x[0]===woodId);const fallback=document.getElementById('at-wood-viewer').querySelector('img');if(fallback){fallback.src='/assets/'+wood[3];fallback.alt='Representative '+wood[1]+' grain';}const region=document.getElementById('at-wood-region');for(const option of region.options)option.disabled=!F.choices[option.value]?.includes(woodId);if(!F.choices[region.value]?.includes(woodId))region.value='wood';document.getElementById('at-wood-name').textContent=wood[1];document.getElementById('at-wood-copy').textContent=wood[2];root.querySelectorAll('[data-at=wood]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));root.querySelector('[data-at=apply-wood]').textContent='Use '+wood[1].toLowerCase()+' in my design ↗';window.dispatchEvent(new CustomEvent('fostinis:material',{detail:{id:woodId,image:'/assets/'+wood[3]}}));}
 else if(action==='apply-wood'){const build=snapshot(),region=document.getElementById('at-wood-region').value;if(!F.choices[region]?.includes(woodId))throw Error('This wood is not available for that region. Choose another region or wood.');studio.restoreBuild({...build,selections:{...build.selections,[region]:woodId}});location.href='/showroom.html#builder';}
 }catch(error){toast(error.message);if(b.isConnected)b.disabled=false;}}
async function init(){if(!F||!studio?.ready)return;document.addEventListener('click',handle);if(!document.body.dataset.atelier){addBuilderEntries();return;}root=document.createElement('div');root.id='atelier-root';document.body.append(root);document.body.classList.add('atelier-ready');const pages={home,materials,sound,craft};if(pages[view])root.innerHTML=header()+`<div id="at-content" role="main">${pages[view]()}</div>`+footer();else if(view==='collection')await collectionPage();else if(view==='commission')await commissionPage();else if(view==='circle')await circlePage();else if(view==='journal')await journalPage();else if(view==='compare')await pollPage();else if(view==='workshop')await workshopPage();else root.innerHTML=header()+home()+footer();
 const titles={home:'The Fostinis Atelier',materials:'The Wood Library',sound:'The Listening Room',craft:'The Fostinis Standard',collection:'My Fostinis Collection',circle:'The Fostinis Circle',commission:'Your Personal Commission',journal:'Your Private Journal',workshop:'The Workshop Desk',compare:'Help Choose a Fostinis'};document.title=(titles[view]||titles.home)+' — Fostinis Guitars';metric('atelier_visit');
 if(view==='materials'){try{const materialModule=await import('/atelier-materials.js?v=61');materialsCleanup=await materialModule.mountMaterials(document.getElementById('at-wood-viewer'));}catch{document.getElementById('at-wood-viewer').querySelector('p').textContent='Interactive rotation is unavailable on this device. Explore the grain photographs and wood choices below.';}}
 document.getElementById('at-import')?.addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Choose a Fostinis backup smaller than 1 MB.');const builds=parseBuildBackup(await file.text(),F);if(!collection)await loadCollection();if(collection.builds.length+builds.length>20)throw Error('This import would exceed the 20-design collection limit.');await storeCollection([...builds.map(b=>({...b,id:crypto.randomUUID(),image:'',createdAt:new Date().toISOString()})),...collection.builds]);refreshCollection();toast('Your designs are imported.');}catch(e){toast(e.message);}event.target.value='';});
}
init().catch(e=>{toast('The atelier could not open: '+e.message);});
window.addEventListener('pagehide',()=>materialsCleanup?.(),{once:true});
